import { useState } from 'react';
import type { CampaignState } from '@the-system/engine';
import { friendlyError } from '../format';
import type { LiveClient } from '../live';
import { cssToken } from '../player/sheet';
import {
  cancelOfferCommand,
  gmOffers,
  removeShopCommand,
  saleCommand,
  saleOpen,
  shopRows,
  type ShopRow,
  type ShopWareRow,
} from './shopsModel';

type Outcome = { ok: boolean; text: string } | null;

/**
 * GM shops (ROADMAP MC.3, DESIGN §11 "Shops"): the shops the GM has added or
 * imported (often generated by the co-DM). Shops are GM-side: the GM
 * narrates, and "Sell" on a ware offers it to the chosen character as a GM
 * trade at the listed price, which the player accepts or declines. The GM's
 * open offers are listed to cancel; a shop can be removed (MC.3 review).
 */
export function Shops({ client, state }: { client: LiveClient; state: CampaignState }) {
  const shops = shopRows(state);
  const currency = state.rules.economy.currencyName;
  const rarityName = (id: string) =>
    state.rules.skills.rarities.find((r) => r.id === id)?.name ?? id;
  const ids = state.characterOrder.filter((id) => state.characters[id]);
  const [who, setWho] = useState('');
  const characterId = ids.includes(who) ? who : (ids[0] ?? '');
  const [busy, setBusy] = useState(false);
  const [outcome, setOutcome] = useState<Outcome>(null);

  const sell = async (ware: ShopWareRow) => {
    const command = saleCommand(characterId, ware);
    if (!command) return;
    setBusy(true);
    const r = await client.command(command);
    setBusy(false);
    const name = state.characters[characterId]?.name ?? '';
    setOutcome(
      r.ok
        ? {
            ok: true,
            text: `Offered [${ware.name}] to ${name} for ${ware.price} ${currency}: waiting for ${name} to accept`,
          }
        : { ok: false, text: friendlyError(r.error) },
    );
  };

  const run = async (command: Parameters<LiveClient['command']>[0], done: string) => {
    setBusy(true);
    const r = await client.command(command);
    setBusy(false);
    setOutcome(r.ok ? { ok: true, text: done } : { ok: false, text: friendlyError(r.error) });
  };
  const remove = (shop: ShopRow) => {
    if (!window.confirm(`Remove the shop [${shop.name}]? Its items stay in the library.`)) return;
    void run(removeShopCommand(shop.id), `[${shop.name}] removed`);
  };
  const offers = gmOffers(state);

  return (
    <section className="window shops" aria-labelledby="shops-heading">
      <h2 id="shops-heading">Shops</h2>
      {shops.length === 0 ? (
        <p className="muted">No shops yet. Import one, or ask the co-DM to generate a shop.</p>
      ) : (
        <>
          <label>
            Sell to
            <select value={characterId} onChange={(e) => setWho(e.target.value)}>
              {ids.length === 0 && <option value="">No characters yet</option>}
              {ids.map((id) => (
                <option key={id} value={id}>
                  {state.characters[id]?.name}
                </option>
              ))}
            </select>
          </label>
          {shops.map((shop) => (
            <article key={shop.id} className="shop" aria-label={shop.name}>
              <h3>[{shop.name}]</h3>
              {shop.place && <p className="muted">In {shop.place}</p>}
              {shop.keeper && (
                <p>
                  <strong>Keeper:</strong> {shop.keeper}
                </p>
              )}
              {shop.wares.length === 0 ? (
                <p className="muted">Nothing for sale.</p>
              ) : (
                <ul className="shop-wares">
                  {shop.wares.map((w, i) => (
                    <li key={`${w.itemId}-${i}`}>
                      <span className={`rarity-${cssToken(w.rarity)}`}>
                        [{w.name}] ({rarityName(w.rarity)})
                      </span>{' '}
                      <span>
                        {w.price} {currency}
                      </span>{' '}
                      <button
                        type="button"
                        disabled={
                          busy || characterId === '' || saleOpen(state, characterId, w.itemId)
                        }
                        title={
                          saleOpen(state, characterId, w.itemId)
                            ? 'Already offered: waiting for an answer'
                            : undefined
                        }
                        aria-label={`Sell ${w.name}`}
                        onClick={() => void sell(w)}
                      >
                        Sell
                      </button>
                    </li>
                  ))}
                </ul>
              )}
              {shop.hook && (
                <p>
                  <strong>Hook:</strong> {shop.hook}
                </p>
              )}
              <button type="button" disabled={busy} onClick={() => remove(shop)}>
                Remove shop
              </button>
            </article>
          ))}
        </>
      )}
      {offers.length > 0 && (
        <>
          <h3 id="gm-offers-heading">Your open offers</h3>
          <ul aria-labelledby="gm-offers-heading" className="gm-offers">
            {offers.map((o) => (
              <li key={o.tradeId}>
                To {o.who}: {o.text}{' '}
                <button
                  type="button"
                  disabled={busy}
                  aria-label={`Cancel the offer to ${o.who}: ${o.text}`}
                  onClick={() =>
                    void run(cancelOfferCommand(o.tradeId), `Offer to ${o.who} cancelled`)
                  }
                >
                  Cancel
                </button>
              </li>
            ))}
          </ul>
        </>
      )}
      {outcome && (
        <p className={outcome.ok ? 'ok' : 'err'} role={outcome.ok ? 'status' : 'alert'}>
          {outcome.text}
        </p>
      )}
    </section>
  );
}
